UPDATE knowledge_point k SET history_json = v.history_json, angles_json = v.angles_json, times_seen = v.times_seen, mastery = v.mastery, status = v.status, updated_at = v.updated_at FROM (VALUES
(CAST(#{it.id} AS bigint), #{it.historyJson}, #{it.anglesJson}, CAST(#{it.timesSeen} AS integer), CAST(#{it.mastery} AS double precision), #{it.status}, CAST(#{it.updatedAt} AS bigint))
) AS v(id, history_json, angles_json, times_seen, mastery, status, updated_at) WHERE k.id = v.id AND k.user_id = #{userId}
